<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">Budgets</h1></div><div class="row"><div class="col-lg-4"><?php if(can('budgets.create')):?><div class="card"><div class="card-header"><h5 class="card-title mb-0">Create Budget</h5></div><div class="card-body"><form method="post" action="<?=url('budgets')?>"><?=csrf_field()?><select class="form-select mb-2" name="category_id"><option value="">All Categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><input class="form-control mb-2" type="date" name="start_date" required value="<?=date('Y-m-01')?>"><input class="form-control mb-2" type="date" name="end_date" required value="<?=date('Y-m-t')?>"><input class="form-control mb-3" type="number" step="0.01" min="0.01" name="budget_amount" placeholder="Budget amount" required><button class="btn btn-primary">Create Budget</button></form></div></div><?php endif;?></div><div class="col-lg-8"><div class="card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Period</th><th>Category</th><th>Budget</th><th>Spent</th><th>Remaining</th><th>Usage</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$pct=$r['budget_amount']>0?($r['spent']/$r['budget_amount'])*100:0;$remaining=$r['budget_amount']-$r['spent'];?><tr><td><?=e($r['start_date'])?> → <?=e($r['end_date'])?></td><td><?=e($r['category_name']??'All Categories')?></td><td><?=money($r['budget_amount'])?></td><td><?=money($r['spent'])?></td><td class="<?=($remaining<0?'text-danger':'')?>"><?=money($remaining)?></td><td style="min-width:140px"><div class="progress"><div class="progress-bar <?=($pct>=100?'bg-danger':($pct>=90?'bg-warning':''))?>" style="width:<?=min(100,$pct)?>%"></div></div><small><?=number_format($pct,1)?>%</small></td><td><form method="post" action="<?=url('budgets/'.$r['id'].'/delete')?>" onsubmit="return confirm('Delete budget?');"><?=csrf_field()?><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div>